//! Plan explanations on top of the store.
//!
//! A plan generated by this version stores its explanation under `diagnostics.explain`; an older
//! plan is explained when it is read, from its own stored diagnostics and its predecessor's (see
//! [`quant_core::explain`]). This module loads both, and renders the one-line "why" used by
//! notifications.

use std::collections::{BTreeMap, HashMap};

use anyhow::Result;
use deadpool_postgres::GenericClient;
use quant_core::explain::{
    self, EXPLAIN_VERSION, Headline, NoActionReason, OrderDriver, OrderRecord, PlanDriver,
    PlanExplanation, PlanHeader, PlanSnapshot,
};
use quant_core::rebalance::BandWaiver;
use serde::Serialize;
use serde_json::Value;

use crate::store::settings::Lang;
use crate::store::trading::{self, Order, Plan, f};

/// Drivers in the one-line "why".
pub const HEADLINE_DRIVERS: usize = 3;

pub fn header(plan: &Plan) -> PlanHeader {
    PlanHeader {
        id: plan.id,
        status: plan.status.clone(),
        strategy_version_id: plan.strategy_version_id,
        nav: f(plan.nav),
        cash: f(plan.cash),
        exposure_target: plan.exposure_target,
        invested_target: plan.invested_target,
        breadth: plan.breadth,
        est_vol: plan.est_vol,
    }
}

pub fn order_record(order: &Order) -> Option<OrderRecord> {
    Some(OrderRecord {
        symbol: order.symbol.clone(),
        side: quant_core::costs::Side::parse(&order.side)?,
        qty: f(order.qty),
        weight_before: order.weight_before,
        weight_target: order.weight_target,
        weight_after: order.weight_after,
        status: order.status.clone(),
        status_reason: order.status_reason.clone(),
        filled_qty: f(order.filled_qty),
    })
}

/// A stored plan as the explanation needs it (`None` for a plan without engine output).
pub async fn snapshot(
    client: &impl GenericClient,
    plan: &Plan,
    diagnostics: &Value,
) -> Result<Option<PlanSnapshot>> {
    if diagnostics.get("targets").is_none() {
        return Ok(None);
    }
    let orders = trading::orders_for_plan(client, plan.id)
        .await?
        .iter()
        .filter_map(order_record)
        .collect();
    Ok(PlanSnapshot::from_stored(header(plan), diagnostics, orders))
}

/// The plan's explanation: the stored one, or computed now from the plan and its predecessor.
pub async fn explanation(
    client: &impl GenericClient,
    plan: &Plan,
    diagnostics: &Value,
) -> Result<Option<PlanExplanation>> {
    if let Some(stored) = diagnostics.get("explain")
        && stored.get("version").and_then(Value::as_u64) == Some(EXPLAIN_VERSION as u64)
        && let Ok(x) = serde_json::from_value::<PlanExplanation>(stored.clone())
    {
        return Ok(Some(x));
    }
    let Some(current) = snapshot(client, plan, diagnostics).await? else {
        return Ok(None);
    };
    let previous = previous_snapshot(client, plan.account_id, Some(plan)).await?;
    Ok(Some(explain::explain(&current, previous.as_ref())))
}

/// The account's previous plan with engine output: before `plan`, or the latest one.
pub async fn previous_snapshot(
    client: &impl GenericClient,
    account_id: i64,
    plan: Option<&Plan>,
) -> Result<Option<PlanSnapshot>> {
    let before = plan.map(|p| (p.generated_at, p.id));
    let Some(previous) = trading::previous_explainable_plan(client, account_id, before).await?
    else {
        return Ok(None);
    };
    let diagnostics = trading::plan_diagnostics(client, previous.id).await?;
    snapshot(client, &previous, &diagnostics).await
}

/// Compact headlines for a page of plans: stored ones are read as they are, older plans are
/// explained now.
pub async fn headlines(
    client: &impl GenericClient,
    plans: &[Plan],
) -> Result<HashMap<i64, Headline>> {
    let ids: Vec<i64> = plans.iter().map(|p| p.id).collect();
    let stored = trading::stored_explain_headlines(client, &ids).await?;
    let mut out = HashMap::new();
    for plan in plans {
        if plan.status == "skipped" {
            continue;
        }
        if let Some(value) = stored.get(&plan.id)
            && value.get("version").and_then(Value::as_u64) == Some(EXPLAIN_VERSION as u64)
            && let Ok(headline) = serde_json::from_value::<Headline>(value.clone())
        {
            out.insert(plan.id, trim(headline));
            continue;
        }
        let diagnostics = trading::plan_diagnostics(client, plan.id).await?;
        if let Some(x) = explanation(client, plan, &diagnostics).await? {
            out.insert(plan.id, x.headline(HEADLINE_DRIVERS));
        }
    }
    Ok(out)
}

fn trim(mut headline: Headline) -> Headline {
    headline.drivers.truncate(HEADLINE_DRIVERS);
    headline
}

/// The driver codes of a headline, for audit entries.
pub fn driver_codes(drivers: &[PlanDriver]) -> Vec<&'static str> {
    drivers.iter().map(PlanDriver::code).collect()
}

// ---------------------------------------------------------------------------------------------
// Exposure panel (Overview): where breadth and exposure stand, what changed since the previous
// plan, and what would trigger the next trades.
// ---------------------------------------------------------------------------------------------

#[derive(Debug, Clone, Serialize)]
pub struct ExposurePoint {
    pub plan_id: i64,
    pub trade_date: chrono::NaiveDate,
    pub slot: String,
    pub breadth: Option<f64>,
    pub exposure_target: Option<f64>,
    pub invested_target: Option<f64>,
}

/// How much of its drift band a holding has used against the latest plan's target: it trades
/// at the next plan when |drift| exceeds `band` (or when the cash gap waives bands).
#[derive(Debug, Clone, Serialize)]
pub struct BandDistance {
    pub symbol: String,
    pub weight: f64,
    pub target: f64,
    /// `target − weight`.
    pub drift: f64,
    pub band: f64,
}

/// Why a name has its target weight: sector budget × share within the sector, and the signals
/// behind the share.
#[derive(Debug, Clone, Serialize)]
pub struct WeightWhy {
    pub sector: String,
    pub sector_weight: f64,
    pub share: f64,
    pub vol: Option<f64>,
    pub momentum_multiplier: f64,
    pub trend_multiplier: f64,
    pub breadth_gap: Option<f64>,
    pub capped: bool,
    pub target: f64,
}

#[derive(Debug, Clone, Serialize)]
pub struct ExposureView {
    pub plan_id: i64,
    pub trade_date: chrono::NaiveDate,
    pub slot: String,
    pub generated_at: chrono::DateTime<chrono::Utc>,
    pub previous_plan_id: Option<i64>,
    pub breadth_scaling: bool,
    /// Breadth moving-average length and the exposure range it maps onto.
    pub line: usize,
    pub min_exposure: f64,
    pub max_exposure: f64,
    pub min_history_days: usize,
    pub breadth: Option<f64>,
    pub above: Option<usize>,
    pub counted: Option<usize>,
    pub exposure_target: Option<f64>,
    pub invested_target: Option<f64>,
    pub crossed_below: Vec<String>,
    pub crossed_above: Vec<String>,
    /// Invested weight now (live valuation) and its gap to the plan's target.
    pub invested_now: f64,
    pub cash_gap: Option<f64>,
    pub cash_band: f64,
    pub triggers: Option<quant_core::explain::BreadthTriggers>,
    pub history: Vec<ExposurePoint>,
    pub bands: Vec<BandDistance>,
    pub weights: BTreeMap<String, WeightWhy>,
}

/// The exposure panel for an account, from its latest plan with engine output and the live
/// weights (`(symbol, weight)` and the invested share of NAV).
pub async fn exposure_view(
    client: &impl GenericClient,
    account_id: i64,
    live_weights: &[(String, f64)],
    invested_now: f64,
) -> Result<Option<ExposureView>> {
    let Some(latest) = trading::previous_explainable_plan(client, account_id, None).await? else {
        return Ok(None);
    };
    let diagnostics = trading::plan_diagnostics(client, latest.id).await?;
    let Some(snapshot) = snapshot(client, &latest, &diagnostics).await? else {
        return Ok(None);
    };
    let x = explanation(client, &latest, &diagnostics).await?;
    let params = &snapshot.params;

    let (history, _) = trading::list_plans(
        client,
        account_id,
        &trading::PlanFilter {
            from: None,
            to: None,
            status: None,
            limit: 120,
            offset: 0,
        },
    )
    .await?;
    let mut history: Vec<ExposurePoint> = history
        .into_iter()
        .filter(|p| p.status != "skipped" && p.exposure_target.is_some())
        .map(|p| ExposurePoint {
            plan_id: p.id,
            trade_date: p.trade_date,
            slot: p.slot,
            breadth: p.breadth,
            exposure_target: p.exposure_target,
            invested_target: p.invested_target,
        })
        .collect();
    history.reverse();

    let rp = &params.rebalance;
    let mut bands: Vec<BandDistance> = live_weights
        .iter()
        .filter(|(_, w)| *w > 0.0)
        .map(|(symbol, weight)| {
            let target = snapshot
                .assets
                .iter()
                .find(|a| &a.symbol == symbol)
                .map(|a| a.weight.max(0.0))
                .unwrap_or(0.0);
            BandDistance {
                symbol: symbol.clone(),
                weight: *weight,
                target,
                drift: target - weight,
                band: rp.band_abs.max(rp.band_rel * target),
            }
        })
        .collect();
    bands.sort_by(|a, b| {
        let used = |d: &BandDistance| {
            if d.band > 0.0 {
                d.drift.abs() / d.band
            } else {
                f64::INFINITY
            }
        };
        used(b).total_cmp(&used(a)).then(a.symbol.cmp(&b.symbol))
    });

    let sector_weight = |sector: &str| -> f64 {
        snapshot
            .assets
            .iter()
            .filter(|a| a.sector == sector)
            .map(|a| a.weight.max(0.0))
            .sum()
    };
    let weights = snapshot
        .assets
        .iter()
        .filter(|a| a.weight > 0.0)
        .map(|a| {
            let total = sector_weight(&a.sector);
            (
                a.symbol.clone(),
                WeightWhy {
                    sector: a.sector.clone(),
                    sector_weight: total,
                    share: if total > 0.0 { a.weight / total } else { 0.0 },
                    vol: a.vol,
                    momentum_multiplier: a.momentum_multiplier,
                    trend_multiplier: a.trend_multiplier,
                    breadth_gap: a.breadth_gap,
                    capped: a.capped,
                    target: a.weight,
                },
            )
        })
        .collect();

    let counted = x.as_ref().and_then(|x| x.breadth.counted_now);
    let triggers = match (latest.exposure_target, latest.invested_target) {
        (Some(e), Some(i)) => {
            quant_core::explain::breadth_triggers(params, invested_now, e, i, counted)
        }
        _ => None,
    };
    Ok(Some(ExposureView {
        plan_id: latest.id,
        trade_date: latest.trade_date,
        slot: latest.slot.clone(),
        generated_at: latest.generated_at,
        previous_plan_id: x.as_ref().and_then(|x| x.previous_plan_id),
        breadth_scaling: params.exposure.breadth_scaling,
        line: params.exposure.breadth_sma,
        min_exposure: params.exposure.min_exposure,
        max_exposure: params.exposure.max_exposure,
        min_history_days: params.universe.min_history_days,
        breadth: latest.breadth,
        above: x.as_ref().and_then(|x| x.breadth.above_now),
        counted,
        exposure_target: latest.exposure_target,
        invested_target: latest.invested_target,
        crossed_below: x
            .as_ref()
            .map(|x| x.breadth.crossed_below.clone())
            .unwrap_or_default(),
        crossed_above: x
            .as_ref()
            .map(|x| x.breadth.crossed_above.clone())
            .unwrap_or_default(),
        invested_now,
        cash_gap: latest.invested_target.map(|t| t - invested_now),
        cash_band: quant_core::rebalance::CASH_BAND,
        triggers,
        history,
        bands,
        weights,
    }))
}

// ---------------------------------------------------------------------------------------------
// One-line text (notifications). The web UI renders the same codes with its own dictionaries.
// ---------------------------------------------------------------------------------------------

fn p1(value: f64) -> String {
    format!("{:.1}%", value * 100.0)
}

/// "1 order", "3 orders"; "1 trend recovery", "2 trend recoveries".
fn plural(n: usize, noun: &str) -> String {
    if n == 1 {
        format!("1 {noun}")
    } else if let Some(stem) = noun.strip_suffix('y') {
        format!("{n} {stem}ies")
    } else {
        format!("{n} {noun}s")
    }
}

fn pts(value: f64) -> String {
    format!("{:.1}", value.abs() * 100.0)
}

pub fn order_driver_name(driver: OrderDriver, lang: Lang) -> &'static str {
    use OrderDriver::*;
    match (driver, lang) {
        (FirstPlan, Lang::Zh) => "首个计划",
        (FirstPlan, Lang::En) => "first plan",
        (NewlyEligible, Lang::Zh) => "新满足历史要求",
        (NewlyEligible, Lang::En) => "newly eligible",
        (AddedToUniverse, Lang::Zh) => "新加入股票池",
        (AddedToUniverse, Lang::En) => "added to the universe",
        (BackAboveMinWeight, Lang::Zh) => "回到最小权重之上",
        (BackAboveMinWeight, Lang::En) => "back above the minimum weight",
        (RestrictionLifted, Lang::Zh) => "限制解除",
        (RestrictionLifted, Lang::En) => "restriction lifted",
        (TrendReentry, Lang::Zh) => "重回趋势",
        (TrendReentry, Lang::En) => "trend re-entry",
        (BelowMinWeight, Lang::Zh) => "低于最小权重",
        (BelowMinWeight, Lang::En) => "below the minimum weight",
        (TrendExit, Lang::Zh) => "趋势清仓",
        (TrendExit, Lang::En) => "trend exit",
        (Excluded, Lang::Zh) => "被排除",
        (Excluded, Lang::En) => "excluded",
        (NotInUniverse, Lang::Zh) => "移出股票池",
        (NotInUniverse, Lang::En) => "left the universe",
        (LostEligibility, Lang::Zh) => "不再满足条件",
        (LostEligibility, Lang::En) => "no longer eligible",
        (Exposure, Lang::Zh) => "总仓位",
        (Exposure, Lang::En) => "exposure",
        (SectorBudget, Lang::Zh) => "板块预算",
        (SectorBudget, Lang::En) => "sector budget",
        (Trend, Lang::Zh) => "趋势",
        (Trend, Lang::En) => "trend",
        (Momentum, Lang::Zh) => "动量",
        (Momentum, Lang::En) => "momentum",
        (Volatility, Lang::Zh) => "波动率",
        (Volatility, Lang::En) => "volatility",
        (Peers, Lang::Zh) => "同板块其他公司",
        (Peers, Lang::En) => "peers",
        (NewPeers, Lang::Zh) => "新纳入同板块公司",
        (NewPeers, Lang::En) => "new peers",
        (PriceDrift, Lang::Zh) => "价格漂移",
        (PriceDrift, Lang::En) => "price drift",
        (CarryOverTurnover, Lang::Zh) => "延续换手受限的上一计划",
        (CarryOverTurnover, Lang::En) => "carry-over of a turnover-capped plan",
        (CarryOverCash, Lang::Zh) => "延续现金受限的上一计划",
        (CarryOverCash, Lang::En) => "carry-over of a cash-capped plan",
        (Retry, Lang::Zh) => "重试未成交订单",
        (Retry, Lang::En) => "retry",
    }
}

/// One plan-level driver as a short clause.
pub fn driver_text(
    driver: &PlanDriver,
    lang: Lang,
    sector_name: &dyn Fn(&str, Lang) -> String,
) -> String {
    let zh = lang == Lang::Zh;
    match driver {
        PlanDriver::FirstPlan { eligible, universe } => {
            if zh {
                format!("首个计划，{universe} 只中 {eligible} 只可配置")
            } else {
                format!("first plan, {eligible} of {universe} names eligible")
            }
        }
        PlanDriver::StrategyChanged { .. } => {
            if zh {
                "策略版本已切换".into()
            } else {
                "the strategy version changed".into()
            }
        }
        PlanDriver::HistoryLimited {
            insufficient,
            universe,
        } => {
            if zh {
                format!("{universe} 只中 {insufficient} 只历史数据不足")
            } else {
                format!("{insufficient} of {universe} names lack enough history")
            }
        }
        PlanDriver::NoAction { reason, gap } => match (reason, zh) {
            (NoActionReason::WithinBands, true) => format!(
                "无需交易：投资比例与目标相差 {} 个百分点，未超过 5 点容忍，且每只持仓都在容忍带内",
                pts(*gap)
            ),
            (NoActionReason::WithinBands, false) => format!(
                "nothing to trade: invested weight is {} pts from target, inside the 5-pt tolerance, and every name is inside its band",
                pts(*gap)
            ),
            (NoActionReason::BelowMinTrade, true) => {
                "无需交易：需要的调整都低于最小交易金额".into()
            }
            (NoActionReason::BelowMinTrade, false) => {
                "nothing to trade: every adjustment due is below the minimum trade value".into()
            }
            (NoActionReason::NotTradable, true) => "无需交易：需调整的标的被锁定或缺少报价".into(),
            (NoActionReason::NotTradable, false) => {
                "nothing to trade: the names due are locked or have no usable quote".into()
            }
            (NoActionReason::NothingToTrade, true) => "无需交易：没有持仓也没有目标仓位".into(),
            (NoActionReason::NothingToTrade, false) => {
                "nothing to trade: no holdings and no targets".into()
            }
        },
        PlanDriver::NewlyEligible { count, cut, .. } => match (zh, *cut) {
            (true, 0) => format!("{count} 只公司历史数据已满足要求、新纳入配置"),
            (true, c) => {
                format!("{count} 只公司历史数据已满足要求、新纳入配置，{c} 只原有持仓让出板块预算")
            }
            (false, 0) => format!("{} became eligible and entered", plural(*count, "name")),
            (false, c) => format!(
                "{} became eligible and entered, cutting {} to share their sector budgets",
                plural(*count, "name"),
                plural(c, "existing position")
            ),
        },
        PlanDriver::Breadth {
            line,
            before,
            now,
            crossed_below,
            crossed_above,
            exposure_before,
            exposure_now,
            ..
        } => {
            let crossed = match (*crossed_below, *crossed_above, zh) {
                (0, 0, _) => String::new(),
                (b, 0, true) => format!("，{b} 只跌破 {line} 日线"),
                (b, 0, false) => format!(" ({b} crossed below the {line}-day line)"),
                (0, a, true) => format!("，{a} 只升上 {line} 日线"),
                (0, a, false) => format!(" ({a} crossed above the {line}-day line)"),
                (b, a, true) => format!("，{b} 只跌破、{a} 只升上 {line} 日线"),
                (b, a, false) => {
                    format!(" ({b} crossed below and {a} above the {line}-day line)")
                }
            };
            if zh {
                format!(
                    "市场宽度 {}→{}{crossed}，目标仓位 {}→{}",
                    p1(*before),
                    p1(*now),
                    p1(*exposure_before),
                    p1(*exposure_now)
                )
            } else {
                format!(
                    "breadth {}→{}{crossed}, target exposure {}→{}",
                    p1(*before),
                    p1(*now),
                    p1(*exposure_before),
                    p1(*exposure_now)
                )
            }
        }
        PlanDriver::TrendBreaks { count, orders, .. } => match (zh, *orders) {
            (true, 0) => format!("{count} 只趋势转弱"),
            (true, o) => format!("{count} 只趋势转弱（{o} 笔因此减仓）"),
            (false, 0) => plural(*count, "trend break"),
            (false, o) => format!("{} ({})", plural(*count, "trend break"), plural(o, "order")),
        },
        PlanDriver::TrendRecoveries { count, .. } => {
            if zh {
                format!("{count} 只趋势回升")
            } else {
                plural(*count, "trend recovery")
            }
        }
        PlanDriver::SectorBudget {
            sector,
            before,
            now,
            ..
        } => {
            let name = sector_name(sector, lang);
            if zh {
                format!("{name}板块预算 {}→{}", p1(*before), p1(*now))
            } else {
                format!("{name} budget {}→{}", p1(*before), p1(*now))
            }
        }
        PlanDriver::Orders { driver, orders, .. } => {
            let name = order_driver_name(*driver, lang);
            if zh {
                format!("{orders} 笔源于{name}")
            } else {
                format!("{} from {name}", plural(*orders, "order"))
            }
        }
        PlanDriver::PriceDrift { orders, .. } => {
            if zh {
                format!("{orders} 笔是价格漂移后的再平衡")
            } else {
                format!("{} rebalancing price drift", plural(*orders, "order"))
            }
        }
        PlanDriver::CarryOver {
            previous_cash_scale,
            orders,
            ..
        } => match (zh, previous_cash_scale.is_some()) {
            (true, false) => format!("完成上一计划因换手上限未做完的部分（{orders} 笔）"),
            (true, true) => format!("完成上一计划因现金不足未做完的部分（{orders} 笔）"),
            (false, false) => format!(
                "finishing what the turnover cap left undone last plan ({})",
                plural(*orders, "order")
            ),
            (false, true) => format!(
                "finishing what cash left undone last plan ({})",
                plural(*orders, "order")
            ),
        },
        PlanDriver::Retry { orders, .. } => {
            if zh {
                format!("重试上一计划未成交的 {orders} 笔")
            } else {
                format!(
                    "retrying {} that did not fill last plan",
                    plural(*orders, "order")
                )
            }
        }
        PlanDriver::TurnoverCap { scale, limit } => {
            if zh {
                format!(
                    "受 {:.0}% 换手上限约束，本次只执行 {:.0}%",
                    limit * 100.0,
                    scale * 100.0
                )
            } else {
                format!(
                    "capped by the {:.0}% turnover limit ({:.0}% of the way)",
                    limit * 100.0,
                    scale * 100.0
                )
            }
        }
        PlanDriver::CashCap { scale } => {
            if zh {
                format!("买入受现金约束，按 {:.0}% 执行", scale * 100.0)
            } else {
                format!("buys capped by cash ({:.0}%)", scale * 100.0)
            }
        }
        PlanDriver::BandWaiver {
            side,
            gap,
            invested_now,
            invested_target,
            ..
        } => match (side, zh) {
            (BandWaiver::Sells, true) => format!(
                "已投资 {} 高于目标 {} 达 {} 个百分点，超过 5 点容忍，卖出侧容忍带被跳过",
                p1(*invested_now),
                p1(*invested_target),
                pts(*gap)
            ),
            (BandWaiver::Sells, false) => format!(
                "invested {} was {} pts above the {} target, past the 5-pt tolerance, so sell bands were skipped",
                p1(*invested_now),
                pts(*gap),
                p1(*invested_target)
            ),
            (BandWaiver::Buys, true) => format!(
                "已投资 {} 低于目标 {} 达 {} 个百分点，超过 5 点容忍，买入侧容忍带被跳过",
                p1(*invested_now),
                p1(*invested_target),
                pts(*gap)
            ),
            (BandWaiver::Buys, false) => format!(
                "invested {} was {} pts below the {} target, past the 5-pt tolerance, so buy bands were skipped",
                p1(*invested_now),
                pts(*gap),
                p1(*invested_target)
            ),
        },
        PlanDriver::Frozen { count } => {
            if zh {
                format!("{count} 只被冻结")
            } else {
                format!("{count} frozen")
            }
        }
        PlanDriver::Excluded { count } => {
            if zh {
                format!("{count} 只被排除")
            } else {
                format!("{count} excluded")
            }
        }
    }
}

/// The headline as one line: the first drivers joined, capitalised in English.
pub fn one_line(
    headline: &Headline,
    lang: Lang,
    sector_name: &dyn Fn(&str, Lang) -> String,
) -> String {
    let parts: Vec<String> = headline
        .drivers
        .iter()
        .take(HEADLINE_DRIVERS)
        .map(|d| driver_text(d, lang, sector_name))
        .collect();
    match lang {
        Lang::Zh => {
            let mut text = parts.join("；");
            if !text.is_empty() {
                text.push('。');
            }
            text
        }
        Lang::En => {
            let text = parts.join("; ");
            let mut chars = text.chars();
            match chars.next() {
                Some(first) => format!("{}{}.", first.to_uppercase(), chars.as_str()),
                None => text,
            }
        }
    }
}

/// Sector display names by id, in both languages.
pub type SectorNames = BTreeMap<String, (String, String)>;

pub async fn sector_names(client: &impl GenericClient) -> Result<SectorNames> {
    Ok(crate::store::market::sectors(client)
        .await?
        .into_iter()
        .map(|s| (s.id, (s.name_zh, s.name_en)))
        .collect())
}

pub fn sector_lookup(names: &SectorNames) -> impl Fn(&str, Lang) -> String + '_ {
    move |id, lang| match (names.get(id), lang) {
        (Some((zh, _)), Lang::Zh) => zh.clone(),
        (Some((_, en)), Lang::En) => en.clone(),
        (None, _) => id.to_string(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn none(id: &str, _: Lang) -> String {
        id.to_string()
    }

    #[test]
    fn the_one_line_reads_in_both_languages() {
        let headline = Headline {
            previous_plan_id: Some(16),
            drivers: vec![
                PlanDriver::Breadth {
                    line: 200,
                    before: 0.578125,
                    now: 0.390625,
                    crossed_below: 12,
                    crossed_above: 0,
                    exposure_before: 0.8196875,
                    exposure_now: 0.7484375,
                    orders: 1,
                    weight: 0.002,
                },
                PlanDriver::BandWaiver {
                    side: BandWaiver::Sells,
                    gap: -0.0759,
                    invested_now: 0.8244,
                    invested_target: 0.7484,
                    orders: 18,
                },
                PlanDriver::TrendBreaks {
                    count: 18,
                    orders: 10,
                    weight: 0.04,
                },
            ],
        };
        let en = one_line(&headline, Lang::En, &none);
        assert_eq!(
            en,
            "Breadth 57.8%→39.1% (12 crossed below the 200-day line), target exposure 82.0%→74.8%; \
             invested 82.4% was 7.6 pts above the 74.8% target, past the 5-pt tolerance, so sell \
             bands were skipped; 18 trend breaks (10 orders)."
        );
        let zh = one_line(&headline, Lang::Zh, &none);
        assert!(zh.starts_with("市场宽度 57.8%→39.1%，12 只跌破 200 日线"));
        assert!(zh.ends_with("。"));
    }
}
